#include <Hibernation/ReactionCache.h>
#include <Hibernation/Review.h>
#include <Hibernation/TextPlayback.h>
#include <AYSerializer/JsonSchema.h>
#include <set>
namespace hibernation {
std::string reactionSchema(){return R"({"type":"object","additionalProperties":false,"required":["version","reactions"],"properties":{"version":{"enum":[1]},"reactions":{"type":"array","maxItems":6,"items":{"type":"object","additionalProperties":false,"required":["text","animation"],"properties":{"text":{"type":"string","minLength":1,"maxLength":160},"animation":{"enum":["curious","idle","resting"]}}}}}})";}
ValidatedOutput validateReactions(std::string_view text){std::string value(text);if(value.starts_with("```json\n")&&value.ends_with("```"))value=value.substr(8,value.size()-11);if(!ayt::serializer::validateJsonDocument(value,reactionSchema()))return {false,"reaction_format",{}};auto parsed=Json::parse(value);std::set<std::string> unique;for(const auto& reaction:parsed.at("reactions")){const auto text=reaction.at("text").get<std::string>();if(text.find('\0')!=std::string::npos||text.find_first_of("\r\n")!=std::string::npos||textOffsets(text).size()>41||!unique.insert(text).second)return {false,"reaction_text",{}};}return {true,"ok",std::move(parsed)};}
ReactionGenerator::~ReactionGenerator(){stop();}
bool ReactionGenerator::running()const{return future_.valid();}
void ReactionGenerator::cancel(){if(cancelled_)cancelled_->store(true);}
void ReactionGenerator::stop(){cancel();if(future_.valid()){future_.wait();try{future_.get();}catch(...){}}}
std::optional<ReactionBatch> ReactionGenerator::poll(){if(!future_.valid()||future_.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)return {};return future_.get();}
void ReactionGenerator::start(Profile actor,std::optional<Profile> reviewer,Json persona,Json state,Json excluded,std::string key){if(running())return;cancelled_=std::make_shared<std::atomic<bool>>(false);auto cancel=cancelled_;
    future_=std::async(std::launch::async,[actor=std::move(actor),reviewer=std::move(reviewer),persona=std::move(persona),state=std::move(state),excluded=std::move(excluded),key=std::move(key),cancel]()mutable{ReactionBatch batch;batch.key=key;try{
        const auto started=std::chrono::steady_clock::now();ayt::inference::Request request;request.cancelled=[cancel]{return cancel->load();};request.maxOutputTokens=1024;request.schemaName="interaction_reactions_v1";if(actor.model.supportsJsonSchema)request.outputSchema=reactionSchema();
        request.messages={{"system","你正在为虚拟角色预先准备将来可能使用的短反应，不是在进行当下交谈。只输出给定 JSON，不输出思维链或工具调用。为角色被鼠标轻轻挪动这一常见动作准备最多六条独立、简短、自然且各不相同的反应，每条最多40字。用自身语气，可以不满、玩笑、安静或拒绝，不固定问用户为什么拖动。不能假定方向、次数、距离、痛苦、恋爱关系或用户意图，不能提及缓存、测试、管理程序，不能声称未来动作已经发生。不要把拖动变成当前故事或技术排障话题；不能宣讲人格规则。可以返回空数组表示没有合适反应。已使用或已缓存的原句不能重复。人格："+rolePersona(persona).dump()+"\n格式："+reactionSchema()},{"user",Json{{"state",state},{"excluded",excluded}}.dump()}};
        actor.model.timeout=std::min(actor.model.timeout,std::chrono::milliseconds(20000));ayt::inference::Result result;
        if(actor.model.protocol==ayt::inference::Protocol::Mock){result.text=Json{{"version",1},{"reactions",Json::array({{{"text","脚下的位置换了。"},{"animation","curious"}},{{"text","嗯，这里也可以。"},{"animation","idle"}},{{"text","让我自己站一会儿。"},{"animation","resting"}},{{"text","刚才那一步不算我走的。"},{"animation","curious"}},{{"text","这次落脚挺稳。"},{"animation","idle"}},{{"text","先停在这里吧。"},{"animation","resting"}}})}}.dump();}
        else{result=ayt::inference::invoke(actor.model,request);if(!result){batch.status=cancel->load()?"cancelled":"reaction_model_unavailable";return batch;}}
        batch.modelMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-started).count();batch.proposal=result.text;auto checked=validateReactions(result.text);if(!checked.ok){batch.status=checked.code;return batch;}
        if(reviewer){ayt::inference::Request review;review.cancelled=request.cancelled;review.maxOutputTokens=512;review.schemaName="reaction_review_v1";if(reviewer->model.supportsJsonSchema)review.outputSchema=reviewSchema();review.messages={{"system","审核预先准备的角色动作短反应，只返回规定 JSON。它们是候选，没有真实发生；将来只在实际拖动时消耗一条。检查自然表达、是否机械重复、是否虚构用户意图/次数/方向/关系、是否暴露程序规则。允许不满、拒绝和安静，不要求讨好。approve仅表示这些候选可供使用，不授予工具权限。人格："+rolePersona(persona).dump()+"\n格式："+reviewSchema()},{"user",Json{{"state",state},{"candidate",checked.value},{"excluded",excluded}}.dump()}};reviewer->model.timeout=std::min(reviewer->model.timeout,std::chrono::milliseconds(10000));const auto before=std::chrono::steady_clock::now();auto verdict=ayt::inference::invoke(reviewer->model,review);batch.reviewMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-before).count();auto valid=verdict?validateReview(verdict.text):ValidatedOutput{};batch.review=valid.ok?valid.value:Json(nullptr);if(!valid.ok||valid.value.at("decision")!="approve"){batch.status=cancel->load()?"cancelled":"reaction_review_rejected";return batch;}}
        if(cancel->load()){batch.status="cancelled";return batch;}for(const auto& item:checked.value.at("reactions"))if(std::find(excluded.begin(),excluded.end(),item.at("text"))==excluded.end())batch.entries.push_back(item);batch.status="ok";
    }catch(...){batch.status=cancel->load()?"cancelled":"reaction_generation_failed";}return batch;});
}
Json takeReaction(Json& pool,std::int64_t now){auto& entries=pool["entries"];for(auto it=entries.begin();it!=entries.end();)if(it->value("expires",std::int64_t(0))<=now)it=entries.erase(it);else ++it;for(auto it=entries.begin();it!=entries.end();++it)if(it->value("ready",false)){auto result=*it;entries.erase(it);pool["used"].push_back(result.at("text"));while(pool["used"].size()>64)pool["used"].erase(0);return result;}return nullptr;}
}

